  xLarm := TRUE;
END_IF;
xTrycksatt := (steg >= 2) AND (steg <= 5);
CASE steg OF
  0:
    IF ST500_PEC_PART AND xDriftsklar AND AIR_OK AND NOT xLarm THEN
      steg := 1;
    END_IF;
  1:
    IF ST500_CLP_CLOSED AND xDriftsklar AND NOT xLarm THEN
      steg := 2;
    END_IF;
  2:
    IF tmrFyll.Q AND xDriftsklar AND NOT xLarm THEN
      steg := 3;
    END_IF;
  3:
    IF tmrStab.Q AND xDriftsklar AND NOT xLarm THEN
      steg := 4;
    END_IF;
  4:
    IF tmrMat.Q THEN
      IF ST500_TST_DP <= 0.0 THEN
        xKassera := FALSE;
      ELSIF ST500_TST_DP > 1.5 THEN
        xKassera := TRUE;
      ELSE
        xKassera := FALSE;
      END_IF;
      steg := 5;
    END_IF;
  5:
    IF tmrAvluft.Q THEN
      steg := 6;
    END_IF;
  6:
    IF NOT xLarm THEN
      IF xKassera THEN
        IF ST500_PSH_HOME AND AIR_OK THEN
          steg := 7;
        END_IF;
      ELSE
        steg := 8;
      END_IF;
    END_IF;
  7:
    IF tmrUtskjut.Q THEN
      steg := 8;
    END_IF;
  8:
    IF NOT ST500_PEC_PART THEN
      xKassera := FALSE;
      steg := 0;
    END_IF;
  ELSE
    steg := 0;
END_CASE;
ST500_CNV_RUN := ((steg = 0) OR (steg = 6) OR (steg = 8)) AND xDriftsklar AND NOT xLarm AND EMG_OK AND SYS_AUTO;
ST500_CLP_CLOSE := ((steg >= 1) AND (steg <= 5)) OR xTrycksatt;
ST500_VLV_FILL := (steg = 2) AND xDriftsklar AND EMG_OK AND AIR_OK AND NOT xLarm AND NOT ST500_VLV_VENT;
ST500_VLV_MEAS := (steg = 4) AND tmrStab.Q AND xDriftsklar AND EMG_OK AND AIR_OK AND NOT xLarm;
