tmrStab(IN:=(steg = 3), PT:=T#5s);
tmrMat(IN:=(steg = 4), PT:=T#10s);
tmrAvluft(IN:=((steg = 5) OR (steg = 10)), PT:=T#1s);
tmrUtskjut(IN:=(steg = 7), PT:=T#1s);
