xLarm := TRUE;
END_IF;
IF NOT EMG_OK THEN
steg := 0;
xKassera := FALSE;
ELSE
CASE steg OF
0:
IF ST500_PEC_PART AND xDriftsklar AND AIR_OK AND NOT xLarm THEN
steg := 1;
END_IF;
1:
IF steg = 1 AND tmrKlamma.Q AND NOT ST500_CLP_CLOSED THEN
steg := 9;
ELSIF ST500_CLP_CLOSED AND xDriftsklar AND NOT xLarm THEN
steg := 2;
END_IF;
2:
IF ST500_TST_PRS > 330.0 THEN
steg := 10;
ELSIF tmrFyll.Q THEN
IF ST500_TST_PRS < 270.0 OR ST500_TST_PRS > 330.0 THEN
steg := 10;
ELSIF xDriftsklar AND NOT xLarm THEN
steg := 3;
END_IF;
END_IF;
