xKassera := TRUE;
ELSE
xKassera := FALSE;
END_IF;
steg := 5;
END_IF;
5:
IF tmrAvluft.Q THEN
steg := 6;
END_IF;
6:
IF xKassera THEN
IF ST500_PSH_HOME AND AIR_OK THEN
steg := 7;
END_IF;
ELSE
steg := 8;
END_IF;
7:
IF tmrUtskjut.Q THEN
steg := 8;
END_IF;
8:
IF NOT ST500_PEC_PART THEN
xKassera := FALSE;
steg := 0;
END_IF;
9:
IF NOT xLarm AND NOT ST500_PEC_PART THEN
xKassera := FALSE;
steg := 0;
END_IF;
10:
