END_CASE;
END_IF;
xTrycksatt := ((steg = 2) OR (steg = 3) OR (steg = 4) OR (steg = 5) OR (steg = 10));
ST500_CNV_RUN := ((steg = 0 AND NOT ST500_PEC_PART) OR (steg = 6 AND NOT xKassera) OR (steg = 8)) AND EMG_OK AND SYS_AUTO AND NOT xKravOmstart AND NOT xLarm;
