END_IF;
ST510_LBL_PRINT := (steg = 1) AND xDriftsklar AND EMG_OK AND NOT xLarm AND NOT ST510_LBL_APPLY;
ST510_LBL_APPLY := (steg = 2) AND ST510_PRN_READY AND xDriftsklar AND EMG_OK AND NOT xLarm AND NOT ST510_LBL_PRINT;
ST510_SCN_TRIG := (steg = 3) AND xDriftsklar AND EMG_OK AND NOT xLarm;
ST510_PSH_REJ := (steg = 5) AND AIR_OK AND xDriftsklar AND EMG_OK AND NOT xLarm;
ST510_CNV_RUN := xDriftsklar AND EMG_OK AND NOT xLarm AND SYS_AUTO;
SYS_ALARM := xLarm;
trigReset(CLK:=SYS_RESET);
trigPart(CLK:=ST510_PEC_PART);
trigDone(CLK:=ST510_SCN_DONE);
IF NOT EMG_OK THEN
xKravOmstart := TRUE;
ELSIF trigReset.Q AND EMG_OK THEN
